text:
th[is="tree-view-table-header-cell"] {
  block-size: var(--tree-header-table-height);
  min-inline-size: 5ch;
  padding: 0;
  position: relative;
  overflow: hidden;
  background-color: var(--layout-background-1);

  &[data-type="icon"] {
    inline-size: var(--table-header-cell-icon-width);
    min-inline-size: var(--table-header-cell-icon-min-width);

    & button {
      padding: var(--table-header-cell-icon-button-padding, var(--tree-header-cell-padding));
    }

    & img {
      display: block;
      margin-inline: auto;
    }

    &.last-column {
      inline-size: calc(2 * var(--table-header-cell-icon-width));
      min-inline-size: calc(2 * var(--table-header-cell-icon-min-width));
    }
  }

  & .button-column-picker {
    display: none;
    inset-inline-start: auto;
    inline-size: auto;

    & img {
      content: var(--icon-column-menu);
      margin-inline: 0;
    }

    @media (-moz-overlay-scrollbars) {
      padding-inline-end: env(scrollbar-inline-size);
    }
  }

  &.last-column:not(.column-dragging, .column-moved-by-dragging) .button-column-picker {
    display: unset;
  }

  & hr[is="pane-splitter"] {
    position: absolute;
    inset-inline-end: 4px;
    inset-block: 3px;
    border-inline-start-style: none !important;
    border-inline-end-style: solid;

    &:hover:not(:active, [disabled]) {
      background-color: var(--selected-item-color);
    }
  }

  &:is(.last-column, .column-dragging) hr {
    display: none;
  }

  @media (prefers-reduced-motion: no-preference) {
    &.column-moved-by-dragging {
      transition: transform 200ms ease;
    }
  }
}
